WITH base AS (SELECT *, CAST(amount AS INT) AS amount_int FROM transactions WHERE txn_time >= TO_DATE('2023-05-06')), with_prev AS (SELECT *, LAG(txn_time) OVER (PARTITION BY account_id ORDER BY txn_time ASC, id ASC) AS prev_txn_time FROM base), flagged AS (SELECT *, CASE WHEN prev_txn_time IS NULL OR txn_time > prev_txn_time + INTERVAL 7 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM with_prev), sessionized AS (SELECT id, account_id, amount, txn_time, merchant, amount_int, SUM(session_start_flag) OVER (PARTITION BY account_id ORDER BY txn_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT DATE_TRUNC('YEAR', txn_time) AS year_start, merchant, APPROX_PERCENTILE(amount_int, 0.95) AS amount_int_p95, PERCENTILE_APPROX(session_no, ARRAY(0.25, 0.5, 0.75)) AS session_no_quartiles, MIN(txn_time) AS first_seen, MAX(amount_int) FILTER (WHERE merchant = 'Lazada') AS lazada_max_amount_int, MAX(amount_int) FILTER (WHERE merchant = '7-Eleven') AS 7_eleven_max_amount_int FROM sessionized GROUP BY DATE_TRUNC('YEAR', txn_time), merchant;
